param([Parameter(Mandatory=$true)][string]$RunDirectory,[Parameter(Mandatory=$true)][string]$RomPath,[string]$ExcludedRunDirectory)
$ErrorActionPreference='Stop';$target="$PSScriptRoot/../evidence/mpu4/skill-cash";if((Get-Content "$RunDirectory/exit-code.txt" -Raw).Trim() -ne '0'){throw 'Capture incomplete'};if((Get-FileHash $RomPath -Algorithm SHA1).Hash -ne '402D1518BB78FDC489B06C2AABC771E5CE151847'){throw 'Unexpected ROM'}
$rom=[IO.File]::ReadAllBytes($RomPath);$cases=@(Get-Content "$RunDirectory/cases.json" -Raw|ConvertFrom-Json);$rows=[Collections.Generic.List[object]]::new();$active=$null
foreach($line in (Get-Content "$RunDirectory/debug.log")){if($line -notmatch '^D([SIF]) '){continue};$kind=$Matches[1];$fields=@{};foreach($match in [regex]::Matches($line,'([a-z0-9_]+)=([0-9A-F]+)')){$fields[$match.Groups[1].Value]=[Convert]::ToUInt64($match.Groups[2].Value,16)}
 if($kind -eq 'S'){if($null -ne $active){throw 'Unfinished case'};$active=[ordered]@{case=$cases[[int]$fields.id];instructions=[Collections.Generic.List[object]]::new()}}
 if($null -eq $active -or $fields.id -ne $active.case.id){throw 'Mismatched case'}
 if($kind -in @('S','I')){if($line -notmatch 'bytes=([0-9A-F]{10})'){throw 'Missing context'};$hex=$Matches[1];$pc=[int]$fields.pc;for($n=0;$n -lt 5;$n++){if([Convert]::ToByte($hex.Substring($n*2,2),16) -ne $rom[$pc+$n]){throw 'ROM context differs'}};$active.instructions.Add([ordered]@{pc=$pc;cycle=$fields.cycle;context_hex=$hex})}
 else{if($fields.pc -ne 0x28FE -or $fields.s -ne 0x6FE -or $fields.savedu -ne $active.case.savedU){throw 'Unexpected continuation/frame'};$active['end']=$fields;$active.instructions=@($active.instructions.ToArray());$rows.Add($active);$active=$null}}
if($null -ne $active -or $rows.Count -ne 64 -or $cases.Count -ne 64){throw 'Truncated dispatch capture'}
$regions=@(foreach($r in @(@(0xFE66,84),@(0x719C,1),@(0xFFF4,2))){[ordered]@{address=$r[0];bytes_hex=[Convert]::ToHexString($rom[$r[0]..($r[0]+$r[1]-1)])}})
[ordered]@{classification='Synthetic original bank0 timer1 dispatch including ignored SWI2. Exact regions include following/unexecuted code; five-byte contexts are not instruction lengths.';native_regions=$regions;rows=@($rows.ToArray())}|ConvertTo-Json -Depth 8|Set-Content "$target/timer1-dispatch-timing.json"
[ordered]@{source_run=$RunDirectory;debug_sha256=(Get-FileHash "$RunDirectory/debug.log").Hash;cases_sha256=(Get-FileHash "$RunDirectory/cases.json").Hash;rom_sha1=(Get-FileHash $RomPath -Algorithm SHA1).Hash;provenance=(Get-Content "$RunDirectory/provenance.json" -Raw|ConvertFrom-Json);cases=$rows.Count}|ConvertTo-Json -Depth 5|Set-Content "$target/timer1-dispatch-timing-verification.json";Write-Output 'Curated64 native timer1 dispatch calls'
if($ExcludedRunDirectory){$v=Get-Content "$target/timer1-dispatch-timing-verification.json" -Raw|ConvertFrom-Json;$v|Add-Member -NotePropertyName excluded -NotePropertyValue ([ordered]@{source_run=$ExcludedRunDirectory;debug_sha256=(Get-FileHash "$ExcludedRunDirectory/debug.log").Hash;reason='Initial latch1/control42 experiment allowed repeated physical IRQs after native ANDCC, preempting the selected isolated path. Owned run aborted; accepted experiment keeps the flag but disables timer1 IRQ with control02.'});$v|ConvertTo-Json -Depth 6|Set-Content "$target/timer1-dispatch-timing-verification.json"}
